-- ============================================================
--  Waterproofing+  ·  Supabase database setup
--  HOW TO USE: In Supabase, open  SQL Editor -> New query,
--  paste this ENTIRE file, and click  Run.  Safe to re-run.
-- ============================================================

create table if not exists services (
  id text primary key, name text, sort int
);
create table if not exists materials (
  id text primary key, name text, category text, unit text, step numeric default 1,
  pack text, units_per_pallet numeric default 0, unit_cost numeric default 0,
  on_hand numeric default 0, reorder_at numeric default 0, location text
);
create table if not exists tools (
  id text primary key, name text, service text, battery boolean default false,
  status text default 'in', condition text default 'good', last_charged timestamptz,
  out_by text, out_job text, out_service text, notes text
);
create table if not exists trucks (
  id text primary key, name text, km numeric default 0, last_serviced date, last_oil_km numeric
);
create table if not exists truck_tasks (
  id text primary key, task text, service text, freq text default 'daily'
);
create table if not exists jobs (
  id text primary key, name text, client text, address text, active boolean default true
);
create table if not exists crew (
  id text primary key, name text, email text, points int default 0
);
create table if not exists material_log (
  id bigint generated by default as identity primary key, ts timestamptz default now(),
  material_id text, qty numeric, action text, job_id text, service text, crew_id text, note text
);
create table if not exists tool_log (
  id bigint generated by default as identity primary key, ts timestamptz default now(),
  tool_id text, action text, job_id text, service text, crew_id text, note text
);
create table if not exists truck_logs (
  id bigint generated by default as identity primary key, ts timestamptz default now(),
  truck_id text, km numeric, driver text, job_id text, service text, oil boolean, fuel boolean, repairs text
);
create table if not exists task_completions (
  crew_id text, task_id text, period_key text, done_at timestamptz default now(),
  primary key (crew_id, task_id)
);

-- Atomic material logging: records the entry AND adjusts stock in one safe step
-- (prevents two crew members from overwriting each other's counts).
create or replace function log_material(
  p_material_id text, p_qty numeric, p_action text, p_job_id text,
  p_service text, p_crew_id text, p_note text, p_delta numeric
) returns numeric as $$
declare new_qty numeric;
begin
  values (p_material_id,p_qty,p_action,p_job_id,p_service,p_crew_id,p_note);
  update materials set on_hand = greatest(0, on_hand + p_delta)
  where id = p_material_id returning on_hand into new_qty;
  return new_qty;
end; $$ language plpgsql;


