-- Turn on row-level security and allow the app's public key to read/write.
-- (This keeps Supabase happy now; we add proper crew logins later.)
alter table services enable row level security;
drop policy if exists "app access" on services;
create policy "app access" on services for all using (true) with check (true);
alter table materials enable row level security;
drop policy if exists "app access" on materials;
create policy "app access" on materials for all using (true) with check (true);
alter table tools enable row level security;
drop policy if exists "app access" on tools;
create policy "app access" on tools for all using (true) with check (true);
alter table trucks enable row level security;
drop policy if exists "app access" on trucks;
create policy "app access" on trucks for all using (true) with check (true);
alter table truck_tasks enable row level security;
drop policy if exists "app access" on truck_tasks;
create policy "app access" on truck_tasks for all using (true) with check (true);
alter table jobs enable row level security;
drop policy if exists "app access" on jobs;
create policy "app access" on jobs for all using (true) with check (true);
alter table crew enable row level security;
drop policy if exists "app access" on crew;
create policy "app access" on crew for all using (true) with check (true);
alter table material_log enable row level security;
drop policy if exists "app access" on material_log;
create policy "app access" on material_log for all using (true) with check (true);
alter table tool_log enable row level security;
drop policy if exists "app access" on tool_log;
create policy "app access" on tool_log for all using (true) with check (true);
alter table truck_logs enable row level security;
drop policy if exists "app access" on truck_logs;
create policy "app access" on truck_logs for all using (true) with check (true);
alter table task_completions enable row level security;
drop policy if exists "app access" on task_completions;
create policy "app access" on task_completions for all using (true) with check (true);

